-- ============================================================================
-- V910 — 메일 템플릿 시드 (dev)
-- ----------------------------------------------------------------------------
-- 원안: D:\test\primary_data.sql — 선행 프로젝트의 tb_mail_template 10건.
--   · PK 를 규약 형식으로 교정: 원본은 접두어 없는 raw UUID(36자)라
--     conventions §1(대문자 3자 + "_" + UUIDv7 = 40자)에 맞지 않는다 → MTP_ 접두어 부여.
--   · 본문·변수 힌트는 원문 그대로 유지(발송 기능 도입 시 그대로 쓰기 위함).
--
-- devdata 에 둔 이유: 메일 발송 기능이 아직 없어 지금은 참조용 자료다.
--   기능 구현 시 운영 기준 데이터로 승격한다(인증 기준 데이터와 같은 경로 — PLAN 리스크 표).
--
-- ※ 같은 파일의 tb_member 5건은 <b>싣지 않았다</b>. 이유는 PLAN.md 참조:
--   컬럼 불일치(PASSWORD/STATUS/group_ids) · 존재하지 않는 site_id 참조 ·
--   다른 프로젝트 키로 암호화된 {AG} 값(복호화 불가) · 실제 인물의 개인정보.
-- ============================================================================

insert  into `tb_mail_template`(`mail_template_id`,`template_code`,`template_name`,`subject`,`body_html`,`sender_email`,`sender_name`,`description`,`variables_hint`,`use_yn`,`delete_yn`,`created_by`,`created_ip`,`created_at`,`updated_by`,`updated_ip`,`updated_at`) values 
('MTP_019daf52-e873-7afc-a2c4-e2d825166028','MEMBER_WELCOME','회원가입 축하','[GoPCMS] {{siteName}} 가입을 환영합니다','<!DOCTYPE html>\n<!--\n  회원가입 축하 메일 — MemberServiceImpl.join() 직후 발송.\n  모델 변수:\n    memberName : 회원 이름 (PII)\n    loginId    : 로그인 ID\n    siteName   : 가입한 사이트명 (SiteContext)\n    sentAt     : 발송 일시 (LocalDateTime)\n    loginUrl   : 로그인 URL (예: https://example.go.kr/member/login)\n-->\n<html xmlns:th=\"http://www.thymeleaf.org\" lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <title>회원가입을 환영합니다</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,\'Helvetica Neue\',Arial,sans-serif;color:#0f172a;\">\n  <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#f8fafc;padding:24px 0;\">\n    <tr>\n      <td align=\"center\">\n        <table role=\"presentation\" width=\"560\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n               style=\"background-color:#ffffff;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;\">\n\n          <!-- 헤더 -->\n          <tr>\n            <td style=\"padding:24px 32px;border-bottom:1px solid #e2e8f0;background:linear-gradient(135deg,#0f172a 0%,#1e40af 100%);\">\n              <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"width:40px;height:40px;background-color:#ffffff;border-radius:8px;color:#0f172a;text-align:center;font-weight:700;font-size:20px;line-height:40px;\">G</td>\n                  <td style=\"padding-left:12px;color:#ffffff;\">\n                    <div style=\"font-weight:700;font-size:18px;\">GoPCMS</div>\n                    <div style=\"font-size:12px;opacity:0.8;\" th:text=\"${siteName} ?: \'GoPCMS\'\">기본 사이트</div>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <!-- 본문 -->\n          <tr>\n            <td style=\"padding:32px;\">\n              <div style=\"display:inline-block;background-color:#dbeafe;color:#1e40af;font-size:12px;font-weight:600;padding:4px 10px;border-radius:4px;letter-spacing:0.3px;margin-bottom:12px;\">WELCOME</div>\n              <h1 style=\"margin:0 0 16px 0;font-size:22px;line-height:1.4;color:#0f172a;\">\n                <span th:text=\"${memberName}\">홍길동</span>님, <br/>회원가입을 환영합니다 ?\n              </h1>\n              <p style=\"margin:0 0 20px 0;font-size:14px;line-height:1.7;color:#334155;\">\n                <strong th:text=\"${siteName} ?: \'GoPCMS\'\">GoPCMS</strong> 에 가입해 주셔서 진심으로 감사합니다.\n                이제 모든 서비스를 편리하게 이용하실 수 있습니다.\n              </p>\n\n              <!-- 계정 정보 -->\n              <div style=\"margin:20px 0;padding:16px 20px;background-color:#f1f5f9;border:1px solid #e2e8f0;border-radius:6px;\">\n                <div style=\"font-size:11px;color:#64748b;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px;\">내 로그인 ID</div>\n                <div style=\"font-family:ui-monospace,\'SFMono-Regular\',\'SF Mono\',Menlo,Consolas,monospace;font-size:15px;color:#0f172a;font-weight:600;\"\n                     th:text=\"${loginId}\">example_user</div>\n              </div>\n\n              <!-- 액션 -->\n              <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:24px 0;\">\n                <tr>\n                  <td>\n                    <a th:href=\"${loginUrl} ?: \'#\'\"\n                       style=\"display:inline-block;background-color:#2563eb;color:#ffffff;font-weight:600;font-size:14px;padding:12px 24px;border-radius:6px;text-decoration:none;\">\n                      로그인하고 시작하기 →\n                    </a>\n                  </td>\n                </tr>\n              </table>\n\n              <!-- 시작 가이드 -->\n              <h2 style=\"margin:28px 0 12px 0;font-size:15px;color:#0f172a;\">? 시작하기 전에</h2>\n              <ul style=\"margin:0 0 16px 20px;padding:0;font-size:13px;line-height:1.8;color:#334155;\">\n                <li>마이페이지에서 프로필을 완성해 주세요.</li>\n                <li>비밀번호는 주기적으로 변경하시는 것을 권장합니다.</li>\n                <li>본인확인을 위해 이메일 주소는 최신 상태로 유지해 주세요.</li>\n              </ul>\n\n              <div style=\"margin-top:28px;padding-top:16px;border-top:1px dashed #e2e8f0;\">\n                <p style=\"margin:0;font-size:12px;color:#94a3b8;\">\n                  가입 일시:\n                  <span th:text=\"${#temporals.format(sentAt, \'yyyy-MM-dd HH:mm:ss\')}\">2026-04-21 15:30:00</span>\n                </p>\n              </div>\n            </td>\n          </tr>\n\n          <!-- 푸터 -->\n          <tr>\n            <td style=\"padding:16px 32px;border-top:1px solid #e2e8f0;background-color:#f8fafc;font-size:11px;color:#94a3b8;line-height:1.6;\">\n              본 메일은 GoPCMS 시스템에서 자동 발송되었습니다. 회신이 불가합니다.<br/>\n              본인이 가입하지 않으셨다면 <a href=\"mailto:kingja51@gmail.com\" style=\"color:#64748b;\">고객센터</a>로 문의해 주세요.\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n',NULL,NULL,'회원 가입 완료 직후 발송. MemberServiceImpl.join() 훅.','memberName, loginId, siteName, sentAt, loginUrl','Y','N','SYSTEM','127.0.0.1','2026-04-21 18:15:39','SEEDER','127.0.0.1','2026-04-21 18:16:19'),
('MTP_019daf52-e873-7b88-82dd-0edf141d5508','PASSWORD_CHANGED','비밀번호 변경 알림','[GoPCMS] 비밀번호가 변경되었습니다','<!DOCTYPE html>\n<!--\n  비밀번호 변경 완료 알림 메일 — MemberServiceImpl.changePassword() 직후 발송.\n  보안 목적: 본인이 변경하지 않은 경우 신고할 수 있도록 즉시 통지.\n  모델 변수:\n    memberName  : 회원 이름 (PII)\n    loginId     : 로그인 ID\n    siteName    : 사이트명\n    changedAt   : 변경 일시 (LocalDateTime)\n    clientIp    : 변경 수행 클라이언트 IP (마스킹 권장)\n    userAgent   : User-Agent (요약)\n    supportUrl  : 문의 URL (선택)\n-->\n<html xmlns:th=\"http://www.thymeleaf.org\" lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <title>비밀번호 변경 알림</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,\'Helvetica Neue\',Arial,sans-serif;color:#0f172a;\">\n  <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#f8fafc;padding:24px 0;\">\n    <tr>\n      <td align=\"center\">\n        <table role=\"presentation\" width=\"560\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n               style=\"background-color:#ffffff;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;\">\n\n          <!-- 헤더 -->\n          <tr>\n            <td style=\"padding:24px 32px;border-bottom:1px solid #e2e8f0;\">\n              <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"width:36px;height:36px;background-color:#0f172a;border-radius:6px;color:#ffffff;text-align:center;font-weight:700;font-size:18px;line-height:36px;\">G</td>\n                  <td style=\"padding-left:10px;\">\n                    <div style=\"font-weight:700;font-size:16px;color:#0f172a;\">GoPCMS</div>\n                    <div style=\"font-size:12px;color:#64748b;\">계정 보안 알림</div>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <!-- 본문 -->\n          <tr>\n            <td style=\"padding:28px 32px;\">\n              <div style=\"display:inline-block;background-color:#dcfce7;color:#166534;font-size:12px;font-weight:600;padding:4px 10px;border-radius:4px;letter-spacing:0.3px;margin-bottom:12px;\">SECURITY</div>\n              <h1 style=\"margin:0 0 12px 0;font-size:18px;color:#0f172a;\">비밀번호가 변경되었습니다</h1>\n              <p style=\"margin:0 0 16px 0;font-size:14px;line-height:1.6;color:#334155;\">\n                <strong th:text=\"${memberName}\">홍길동</strong> 님의 계정 비밀번호가 정상적으로 변경되었습니다.\n              </p>\n\n              <!-- 변경 정보 -->\n              <div style=\"margin:20px 0;padding:16px 20px;background-color:#f1f5f9;border:1px solid #e2e8f0;border-radius:6px;\">\n                <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"100%\">\n                  <tr>\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;width:110px;\">로그인 ID</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;font-family:ui-monospace,monospace;\"\n                        th:text=\"${loginId}\">example_user</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;\">변경 일시</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;font-family:ui-monospace,monospace;\"\n                        th:text=\"${#temporals.format(changedAt, \'yyyy-MM-dd HH:mm:ss\')}\">2026-04-21 15:30:00</td>\n                  </tr>\n                  <tr th:if=\"${clientIp}\">\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;\">접속 IP</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;font-family:ui-monospace,monospace;\"\n                        th:text=\"${clientIp}\">192.168.*.*</td>\n                  </tr>\n                  <tr th:if=\"${userAgent}\">\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;vertical-align:top;\">기기 정보</td>\n                    <td style=\"padding:6px 0;font-size:12px;color:#334155;word-break:break-all;\"\n                        th:text=\"${userAgent}\">Mozilla/5.0 (Windows NT 10.0)</td>\n                  </tr>\n                </table>\n              </div>\n\n              <!-- 경고 박스 -->\n              <div style=\"margin:20px 0;padding:14px 16px;background-color:#fef2f2;border-left:4px solid #dc2626;border-radius:4px;\">\n                <p style=\"margin:0;font-size:13px;line-height:1.6;color:#7f1d1d;\">\n                  <strong>본인이 변경하지 않으셨다면</strong> 계정이 탈취됐을 수 있습니다.\n                  즉시 비밀번호를 재설정하고 관리자에게 연락해 주세요.\n                </p>\n              </div>\n\n              <p style=\"margin:16px 0 0 0;font-size:13px;line-height:1.6;color:#334155;\">\n                문의: <a th:href=\"${supportUrl} ?: \'mailto:kingja51@gmail.com\'\"\n                           style=\"color:#2563eb;text-decoration:none;\">고객센터</a>\n              </p>\n            </td>\n          </tr>\n\n          <!-- 푸터 -->\n          <tr>\n            <td style=\"padding:16px 32px;border-top:1px solid #e2e8f0;background-color:#f8fafc;font-size:11px;color:#94a3b8;\">\n              본 메일은 GoPCMS 시스템에서 자동 발송되었습니다. 회신이 불가합니다.\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n',NULL,NULL,'회원 본인이 비밀번호를 변경한 직후 발송 (보안 알림).','memberName, loginId, changedAt, clientIp, userAgent, supportUrl','Y','N','SYSTEM','127.0.0.1','2026-04-21 18:15:39','SEEDER','127.0.0.1','2026-04-21 18:16:19'),
('MTP_019daf52-e873-7bcc-8410-3cf076ed132f','PASSWORD_RESET','임시 비밀번호 발송','[GoPCMS] 임시 비밀번호 발송','<!DOCTYPE html>\n<html xmlns:th=\"http://www.thymeleaf.org\" lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <title>임시 비밀번호 안내</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,\'Helvetica Neue\',Arial,sans-serif;color:#0f172a;\">\n  <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#f8fafc;padding:24px 0;\">\n    <tr>\n      <td align=\"center\">\n        <table role=\"presentation\" width=\"560\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n               style=\"background-color:#ffffff;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;\">\n          <!-- 헤더 -->\n          <tr>\n            <td style=\"padding:24px 32px;border-bottom:1px solid #e2e8f0;\">\n              <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"width:36px;height:36px;background-color:#0f172a;border-radius:6px;color:#ffffff;text-align:center;font-weight:700;font-size:18px;line-height:36px;\">G</td>\n                  <td style=\"padding-left:10px;\">\n                    <div style=\"font-weight:700;font-size:16px;color:#0f172a;\">GoPCMS</div>\n                    <div style=\"font-size:12px;color:#64748b;\">계정 보안 알림</div>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <!-- 본문 -->\n          <tr>\n            <td style=\"padding:28px 32px;\">\n              <h1 style=\"margin:0 0 12px 0;font-size:18px;color:#0f172a;\">임시 비밀번호가 발급되었습니다</h1>\n              <p style=\"margin:0 0 16px 0;font-size:14px;line-height:1.6;color:#334155;\">\n                안녕하세요,\n                <strong th:text=\"${memberName}\" style=\"color:#0f172a;\">홍길동</strong> 님.\n              </p>\n              <p style=\"margin:0 0 16px 0;font-size:14px;line-height:1.6;color:#334155;\">\n                관리자가 회원님의 비밀번호를 초기화했습니다. 아래 임시 비밀번호로 로그인 후\n                <strong>즉시 비밀번호를 변경</strong>해 주세요.\n              </p>\n\n              <div style=\"margin:20px 0;padding:16px;background-color:#f1f5f9;border:1px solid #e2e8f0;border-radius:6px;\">\n                <div style=\"font-size:11px;color:#64748b;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px;\">로그인 ID</div>\n                <div style=\"font-family:ui-monospace,\'SFMono-Regular\',\'SF Mono\',Menlo,Consolas,monospace;font-size:14px;color:#0f172a;margin-bottom:14px;\"\n                     th:text=\"${loginId}\">example_user</div>\n\n                <div style=\"font-size:11px;color:#64748b;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px;\">임시 비밀번호</div>\n                <div style=\"font-family:ui-monospace,\'SFMono-Regular\',\'SF Mono\',Menlo,Consolas,monospace;font-size:18px;font-weight:700;color:#0f172a;letter-spacing:1px;\"\n                     th:text=\"${tempPassword}\">Temp!Pw0rd</div>\n              </div>\n\n              <p style=\"margin:0 0 12px 0;font-size:13px;line-height:1.6;color:#334155;\">\n                <strong style=\"color:#b91c1c;\">보안 주의사항:</strong>\n              </p>\n              <ul style=\"margin:0 0 16px 20px;padding:0;font-size:13px;line-height:1.7;color:#334155;\">\n                <li>임시 비밀번호는 로그인 직후 반드시 변경해 주세요.</li>\n                <li>본 메일은 제3자와 공유하지 마시고, 확인 후 삭제를 권장합니다.</li>\n                <li>비밀번호 초기화를 요청하지 않으셨다면 관리자에게 즉시 문의해 주세요.</li>\n              </ul>\n\n              <p style=\"margin:0;font-size:12px;color:#94a3b8;\">\n                발송 일시:\n                <span th:text=\"${#temporals.format(sentAt, \'yyyy-MM-dd HH:mm:ss\')}\">2026-04-21 15:30:00</span>\n              </p>\n            </td>\n          </tr>\n\n          <!-- 푸터 -->\n          <tr>\n            <td style=\"padding:16px 32px;border-top:1px solid #e2e8f0;background-color:#f8fafc;font-size:11px;color:#94a3b8;\">\n              본 메일은 GoPCMS 시스템에서 자동 발송되었습니다. 회신이 불가합니다.\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n',NULL,NULL,'관리자가 회원 비밀번호를 초기화하고 임시 비밀번호를 메일로 전송.','memberName, loginId, tempPassword, sentAt','Y','N','SYSTEM','127.0.0.1','2026-04-21 18:15:39','SEEDER','127.0.0.1','2026-04-21 18:16:19'),
('MTP_019daf52-e873-7be4-8d32-020cd6943185','ACCOUNT_DORMANT','휴면 계정 전환 안내','[GoPCMS] 휴면 계정 {{stage == \'APPLIED\' ? \'전환 완료\' : \'전환 예정\'}} 안내','<!DOCTYPE html>\n<!--\n  휴면 계정 전환 안내 메일 — 배치(향후 S5) 가 1년 미접속 회원을 tb_member_dormant 로\n  이관하기 전·후 발송. 정책상 30일 전 사전 안내 메일 1회 + 전환 당일 확정 메일 1회.\n  모델 변수:\n    memberName     : 회원 이름 (PII)\n    loginId        : 로그인 ID\n    siteName       : 사이트명\n    lastLoginAt    : 최종 로그인/접속 일시\n    dormantAt      : 휴면 전환 예정/완료 일시\n    stage          : \'NOTICE\' (사전 안내) / \'APPLIED\' (전환 완료)\n    reactivateUrl  : 휴면 해제 안내 URL\n-->\n<html xmlns:th=\"http://www.thymeleaf.org\" lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <title th:text=\"${stage == \'APPLIED\'} ? \'휴면 계정 전환 완료\' : \'휴면 계정 전환 예정 안내\'\">휴면 계정 안내</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,\'Helvetica Neue\',Arial,sans-serif;color:#0f172a;\">\n  <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#f8fafc;padding:24px 0;\">\n    <tr>\n      <td align=\"center\">\n        <table role=\"presentation\" width=\"560\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n               style=\"background-color:#ffffff;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;\">\n\n          <!-- 헤더 -->\n          <tr>\n            <td style=\"padding:24px 32px;border-bottom:1px solid #e2e8f0;\">\n              <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"width:36px;height:36px;background-color:#0f172a;border-radius:6px;color:#ffffff;text-align:center;font-weight:700;font-size:18px;line-height:36px;\">G</td>\n                  <td style=\"padding-left:10px;\">\n                    <div style=\"font-weight:700;font-size:16px;color:#0f172a;\">GoPCMS</div>\n                    <div style=\"font-size:12px;color:#64748b;\"\n                         th:text=\"${siteName} ?: \'기본 사이트\'\">기본 사이트</div>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <!-- 본문 -->\n          <tr>\n            <td style=\"padding:28px 32px;\">\n              <!-- 단계별 배지 -->\n              <div th:if=\"${stage == \'APPLIED\'}\"\n                   style=\"display:inline-block;background-color:#fee2e2;color:#991b1b;font-size:12px;font-weight:600;padding:4px 10px;border-radius:4px;letter-spacing:0.3px;margin-bottom:12px;\">DORMANT APPLIED</div>\n              <div th:unless=\"${stage == \'APPLIED\'}\"\n                   style=\"display:inline-block;background-color:#fef3c7;color:#92400e;font-size:12px;font-weight:600;padding:4px 10px;border-radius:4px;letter-spacing:0.3px;margin-bottom:12px;\">DORMANT NOTICE</div>\n\n              <h1 style=\"margin:0 0 12px 0;font-size:18px;color:#0f172a;\"\n                  th:text=\"${stage == \'APPLIED\'} ? \'계정이 휴면 상태로 전환되었습니다\' : \'휴면 계정 전환 예정 안내\'\">\n                휴면 계정 안내\n              </h1>\n\n              <p style=\"margin:0 0 16px 0;font-size:14px;line-height:1.7;color:#334155;\">\n                안녕하세요, <strong th:text=\"${memberName}\">홍길동</strong> 님.\n              </p>\n\n              <!-- 사전 안내 -->\n              <p th:if=\"${stage != \'APPLIED\'}\"\n                 style=\"margin:0 0 16px 0;font-size:14px;line-height:1.7;color:#334155;\">\n                정보통신망법 제29조 및 시행령에 따라, 일정 기간(1년) 동안 서비스 이용이 없는 계정은\n                개인정보 보호를 위해 <strong>휴면 상태로 전환</strong>됩니다.\n                휴면 전환을 원치 않으시면 전환 예정일 전에 로그인해 주세요.\n              </p>\n\n              <!-- 전환 완료 -->\n              <p th:if=\"${stage == \'APPLIED\'}\"\n                 style=\"margin:0 0 16px 0;font-size:14px;line-height:1.7;color:#334155;\">\n                장기 미접속으로 회원님의 계정이 휴면 상태로 전환되었습니다. 개인정보는 분리된 저장소\n                (<code style=\"font-family:ui-monospace,monospace;\">tb_member_dormant</code>) 에 안전하게 보관됩니다.\n                재사용하시려면 아래 안내에 따라 휴면 해제를 진행해 주세요.\n              </p>\n\n              <!-- 계정 정보 -->\n              <div style=\"margin:20px 0;padding:16px 20px;background-color:#f1f5f9;border:1px solid #e2e8f0;border-radius:6px;\">\n                <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"100%\">\n                  <tr>\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;width:120px;\">로그인 ID</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;font-family:ui-monospace,monospace;\"\n                        th:text=\"${loginId}\">example_user</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;\">최종 접속 일시</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;font-family:ui-monospace,monospace;\"\n                        th:text=\"${lastLoginAt != null ? #temporals.format(lastLoginAt, \'yyyy-MM-dd HH:mm\') : \'-\'}\">2025-04-21 10:00</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;\"\n                        th:text=\"${stage == \'APPLIED\'} ? \'전환 일시\' : \'전환 예정일\'\">전환 예정일</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;font-weight:600;font-family:ui-monospace,monospace;\"\n                        th:text=\"${#temporals.format(dormantAt, \'yyyy-MM-dd\')}\">2026-05-21</td>\n                  </tr>\n                </table>\n              </div>\n\n              <!-- 액션 버튼 -->\n              <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:24px 0;\">\n                <tr>\n                  <td>\n                    <a th:href=\"${reactivateUrl} ?: \'#\'\"\n                       style=\"display:inline-block;background-color:#2563eb;color:#ffffff;font-weight:600;font-size:14px;padding:12px 24px;border-radius:6px;text-decoration:none;\"\n                       th:text=\"${stage == \'APPLIED\'} ? \'휴면 해제하기 →\' : \'지금 로그인해서 휴면 방지 →\'\">\n                      지금 로그인하기\n                    </a>\n                  </td>\n                </tr>\n              </table>\n\n              <!-- 안내 -->\n              <h2 style=\"margin:28px 0 10px 0;font-size:14px;color:#0f172a;\">보관 정책</h2>\n              <ul style=\"margin:0 0 16px 20px;padding:0;font-size:12px;line-height:1.8;color:#334155;\">\n                <li>휴면 전환 후에도 회원님의 개인정보는 법령에 따라 분리 보관됩니다.</li>\n                <li>언제든 본인 확인을 거쳐 휴면을 해제하고 계정을 재사용하실 수 있습니다.</li>\n                <li>일정 기간이 더 경과되면 개인정보는 법령에 따라 자동 파기됩니다.</li>\n              </ul>\n\n              <p style=\"margin:16px 0 0 0;font-size:12px;color:#94a3b8;\">\n                발송 일시:\n                <span th:text=\"${#temporals.format(#temporals.createNow(), \'yyyy-MM-dd HH:mm:ss\')}\">2026-04-21 15:30:00</span>\n              </p>\n            </td>\n          </tr>\n\n          <!-- 푸터 -->\n          <tr>\n            <td style=\"padding:16px 32px;border-top:1px solid #e2e8f0;background-color:#f8fafc;font-size:11px;color:#94a3b8;line-height:1.6;\">\n              본 메일은 GoPCMS 시스템에서 자동 발송되었습니다. 회신이 불가합니다.<br/>\n              문의: <a href=\"mailto:kingja51@gmail.com\" style=\"color:#64748b;\">고객센터</a>\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n',NULL,NULL,'1년 미접속 회원 대상. 30일 전 사전 안내(NOTICE) / 전환 당일(APPLIED) 2단계.','memberName, loginId, siteName, lastLoginAt, dormantAt, stage, reactivateUrl','Y','N','SYSTEM','127.0.0.1','2026-04-21 18:15:39','SEEDER','127.0.0.1','2026-04-21 18:16:19'),
('MTP_019daf52-e873-7bfc-9755-19a878f95bfb','MEMBER_WITHDRAW','회원 탈퇴 완료','[GoPCMS] 회원 탈퇴가 완료되었습니다','<!DOCTYPE html>\n<!--\n  회원 탈퇴 완료 안내 메일 — MemberServiceImpl.withdraw() / adminSoftDelete() 직후 발송.\n  개인정보 파기 전 법정 보관(login_id_hash + ci_hash + retention_expire_at) 안내 포함.\n  모델 변수:\n    memberName        : 회원 이름 (PII, 이 시점에서는 평문)\n    loginId           : 로그인 ID\n    siteName          : 사이트명\n    withdrawAt        : 탈퇴 처리 일시\n    reason            : 사유 (USER_REQUEST / ADMIN_FORCE / DORMANT_EXPIRED)\n    retentionExpireAt : 해시 정보 파기 예정일 (최대 5년 후)\n    rejoinUrl         : 재가입 안내 URL\n-->\n<html xmlns:th=\"http://www.thymeleaf.org\" lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\"/>\n  <title>회원 탈퇴 완료</title>\n</head>\n<body style=\"margin:0;padding:0;background-color:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,\'Helvetica Neue\',Arial,sans-serif;color:#0f172a;\">\n  <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#f8fafc;padding:24px 0;\">\n    <tr>\n      <td align=\"center\">\n        <table role=\"presentation\" width=\"560\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\"\n               style=\"background-color:#ffffff;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;\">\n\n          <!-- 헤더 -->\n          <tr>\n            <td style=\"padding:24px 32px;border-bottom:1px solid #e2e8f0;\">\n              <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"width:36px;height:36px;background-color:#64748b;border-radius:6px;color:#ffffff;text-align:center;font-weight:700;font-size:18px;line-height:36px;\">G</td>\n                  <td style=\"padding-left:10px;\">\n                    <div style=\"font-weight:700;font-size:16px;color:#0f172a;\">GoPCMS</div>\n                    <div style=\"font-size:12px;color:#64748b;\"\n                         th:text=\"${siteName} ?: \'기본 사이트\'\">기본 사이트</div>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <!-- 본문 -->\n          <tr>\n            <td style=\"padding:28px 32px;\">\n              <div style=\"display:inline-block;background-color:#f1f5f9;color:#475569;font-size:12px;font-weight:600;padding:4px 10px;border-radius:4px;letter-spacing:0.3px;margin-bottom:12px;\">WITHDRAWN</div>\n              <h1 style=\"margin:0 0 12px 0;font-size:18px;color:#0f172a;\">회원 탈퇴가 완료되었습니다</h1>\n\n              <p style=\"margin:0 0 16px 0;font-size:14px;line-height:1.7;color:#334155;\">\n                <strong th:text=\"${memberName}\">홍길동</strong> 님,\n                그동안 <strong th:text=\"${siteName} ?: \'GoPCMS\'\">GoPCMS</strong> 를 이용해 주셔서 진심으로 감사드립니다.\n                요청하신 회원 탈퇴 처리가 정상적으로 완료되었습니다.\n              </p>\n\n              <!-- 탈퇴 정보 -->\n              <div style=\"margin:20px 0;padding:16px 20px;background-color:#f1f5f9;border:1px solid #e2e8f0;border-radius:6px;\">\n                <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"100%\">\n                  <tr>\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;width:130px;\">로그인 ID</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;font-family:ui-monospace,monospace;\"\n                        th:text=\"${loginId}\">example_user</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;\">탈퇴 일시</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;font-family:ui-monospace,monospace;\"\n                        th:text=\"${#temporals.format(withdrawAt, \'yyyy-MM-dd HH:mm:ss\')}\">2026-04-21 15:30:00</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 0;font-size:12px;color:#64748b;\">탈퇴 사유</td>\n                    <td style=\"padding:6px 0;font-size:13px;color:#0f172a;\">\n                      <span th:switch=\"${reason}\">\n                        <span th:case=\"\'USER_REQUEST\'\">본인 요청</span>\n                        <span th:case=\"\'ADMIN_FORCE\'\">관리자 처리</span>\n                        <span th:case=\"\'DORMANT_EXPIRED\'\">휴면 기간 만료</span>\n                        <span th:case=\"*\" th:text=\"${reason}\">기타</span>\n                      </span>\n                    </td>\n                  </tr>\n                </table>\n              </div>\n\n              <!-- 보관 정책 안내 -->\n              <div style=\"margin:20px 0;padding:14px 16px;background-color:#fffbeb;border-left:4px solid #f59e0b;border-radius:4px;\">\n                <p style=\"margin:0 0 6px 0;font-size:13px;font-weight:600;color:#78350f;\">개인정보 보관 안내</p>\n                <p style=\"margin:0;font-size:12px;line-height:1.7;color:#78350f;\">\n                  관련 법령(전자상거래법 · 소비자보호법 등)에 따라 최소한의 식별 해시 정보\n                  (login_id_hash, ci_hash) 만\n                  <strong th:text=\"${#temporals.format(retentionExpireAt, \'yyyy-MM-dd\')}\">2031-04-21</strong>\n                  까지 안전하게 분리 보관된 뒤 파기됩니다.\n                  이름·이메일·전화번호 등 PII 는 즉시 삭제되었습니다.\n                </p>\n              </div>\n\n              <p style=\"margin:20px 0 0 0;font-size:13px;line-height:1.7;color:#334155;\">\n                언제든 다시 가입하실 수 있습니다. 다음에 더 나은 서비스로 찾아 뵙겠습니다.\n              </p>\n\n              <!-- 재가입 버튼 -->\n              <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:20px 0;\">\n                <tr>\n                  <td>\n                    <a th:href=\"${rejoinUrl} ?: \'#\'\"\n                       style=\"display:inline-block;background-color:#0f172a;color:#ffffff;font-weight:600;font-size:13px;padding:10px 20px;border-radius:6px;text-decoration:none;\">\n                      다시 가입하기\n                    </a>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <!-- 푸터 -->\n          <tr>\n            <td style=\"padding:16px 32px;border-top:1px solid #e2e8f0;background-color:#f8fafc;font-size:11px;color:#94a3b8;line-height:1.6;\">\n              본 메일은 GoPCMS 시스템에서 자동 발송되었습니다. 회신이 불가합니다.<br/>\n              본인이 탈퇴하지 않으셨다면 즉시\n              <a href=\"mailto:kingja51@gmail.com\" style=\"color:#64748b;\">고객센터</a>로 문의해 주세요.\n            </td>\n          </tr>\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n',NULL,NULL,'본인 요청 또는 관리자 처리로 탈퇴 확정 시 발송.','memberName, loginId, siteName, withdrawAt, reason, retentionExpireAt, rejoinUrl','Y','N','SYSTEM','127.0.0.1','2026-04-21 18:15:39','SEEDER','127.0.0.1','2026-04-21 18:16:19'),
('MTP_019dbde4-4503-7414-947a-8c65c9e03988','ACCOUNT_DORMANT_NOTICE_30D','휴면 전환 30일 전 알림','[GoPCMS] {{memberName}}님, 30일 뒤 휴면 계정으로 전환됩니다','<h2>휴면 계정 전환 예정 안내</h2><p>안녕하세요, <b>{{memberName}}</b>님.</p><p>최종 로그인 시각({{lastLoginAt}})으로부터 일정 기간 접속이 없어 <b>30일 뒤 휴면 계정으로 전환</b>될 예정입니다.</p><p>전환 이전에 <b>로그인 1회</b>만으로도 유지됩니다.</p><p>로그인 ID: <code>{{loginId}}</code></p><hr/><p style=\"color:#888\">본 메일은 발신 전용입니다.</p>',NULL,'GoPCMS','휴면 전환 30일 전 안내','{memberName,loginId,lastLoginAt}','Y','N','SYSTEM','127.0.0.1','2026-04-24 14:09:06',NULL,NULL,'2026-04-24 14:09:06'),
